function validate([s, knowledge]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[a-z()]*$/.test(s)) return 's may contain only lowercase letters and round brackets.';
  if (!/^([a-z]|\([a-z]+\))*$/.test(s)) return 'Brackets in s must form non-nested pairs, each around a non-empty key.';
  if (!Array.isArray(knowledge) || knowledge.length > 100000) return 'knowledge holds at most 10^5 entries.';
  const seen = new Set();
  for (const pair of knowledge) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each knowledge entry is [key, value].';
    for (const text of pair) if (typeof text !== 'string' || !/^[a-z]{1,10}$/.test(text)) return 'Keys and values are 1 to 10 lowercase letters.';
    if (seen.has(pair[0])) return 'Each key appears at most once in knowledge.';
    seen.add(pair[0]);
  }
  return null;
}

