function evaluate(s, knowledge) {
  const values = new Map();
  for (const [key, value] of knowledge) {
    values.set(key, value);
  }

  const parts = [];
  let start = -1;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '(') {
      start = i + 1;
    } else if (ch === ')') {
      const key = s.slice(start, i);
      parts.push(values.has(key) ? values.get(key) : '?');
      start = -1;
    } else if (start === -1) {
      parts.push(ch);
    }
  }
  return parts.join('');
}

