function evaluate(s, knowledge) {
  // Let a regular expression find each pair and look the key up by scanning the list.
  return s.replace(/\(([a-z]+)\)/g, (whole, name) => {
    for (const pair of knowledge) if (pair[0] === name) return pair[1];
    return '?';
  });
}

