function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const word = (letters, lo, hi) => {
    let w = '';
    const len = int(lo, hi);
    for (let i = 0; i < len; i++) w += letters[int(0, letters.length - 1)];
    return w;
  };
  const large = size === 'large';
  const letters = large ? 'abcdef' : 'abc';
  const poolSize = large ? 1500 : int(1, 5);
  const pool = new Set();
  for (let tries = 0; pool.size < poolSize && tries < poolSize * 20; tries++) pool.add(word(letters, 1, large ? 6 : 2));
  const keys = [...pool];
  const knownCount = large ? 1000 : int(0, keys.length);
  const knowledge = [];
  for (let i = 0; i < knownCount; i++) knowledge.push([keys[i], word('abcdefghijklmnopqrstuvwxyz', 1, large ? 10 : 3)]);
  const limit = large ? 9990 : int(1, 14);
  let s = '';
  while (s.length < limit) {
    const piece = rand() < 0.4
      ? '(' + (rand() < 0.85 ? keys[int(0, keys.length - 1)] : word(letters, 1, large ? 8 : 3)) + ')'
      : word(letters, 1, large ? 4 : 2);
    if (s.length + piece.length > (large ? 10000 : 20)) break;
    s += piece;
  }
  if (s.length === 0) s = 'a';
  return [s, knowledge];
}
